<script setup lang="ts">
import { ref, computed, watch, onBeforeUnmount, nextTick } from 'vue';
import { TrendingUp, FileText, MessageSquare, ShieldCheck, ArrowUpRight, History, RefreshCw, AlertCircle, ChevronRight, Search, X, Clock } from 'lucide-vue-next';
import { api } from './api';
import { durationLabel } from './dwellTime';
import ReportExport from './ReportExport.vue';
import TimeStatsPanel from './TimeStatsPanel.vue';
const exportRequest=ref<any>(null);
function exportCourse(){if(!data.value||loading.value)return;exportRequest.value={kind:'course',courseId:props.courseId,courseLabel:props.courseLabel,filters:{q:query.value,assignmentId:assignment.value,authorId:author.value,state:state.value,sort:sort.value},assignmentLabel:assignment.value==='0'?'全部作业':data.value.assignments.find((a:any)=>String(a.id)===assignment.value)?.title||assignment.value,authorLabel:!props.staff?'仅本人':author.value==='0'?'全部作者':data.value.authors.find((a:any)=>String(a.id)===author.value)?.display_name||author.value,stateLabel:tabs.find(t=>t.id===state.value)?.name,total:data.value.total};}
function exportEntry(){if(!detail.value||detailLoading.value)return;exportRequest.value={kind:'entry',courseId:props.courseId,entryId:detail.value.entry.id};}

const props=defineProps<{courseId:number;staff:boolean;userId:number;courseLabel?:string}>();
const emit=defineEmits(['open-version','open-feedback','assignments']);
const data=ref<any>(null),error=ref(''),loading=ref(false),query=ref(''),assignment=ref('0'),author=ref('0'),state=ref('ALL'),sort=ref('recent'),page=ref(1);
const dialog=ref<HTMLDialogElement>(),detail=ref<any>(null),detailError=ref(''),detailLoading=ref(false),versionPage=ref(1),feedbackPage=ref(1),feedbackState=ref('OPEN'),tab=ref('versions');
let alive=true,generation=0,detailGeneration=0,detailId=0,debounce:ReturnType<typeof setTimeout>,returnFocus:HTMLElement|null=null;
const entries=computed<any[]>(()=>data.value?.items||[]),stats=computed(()=>data.value?.summary||{}),pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/20)));
const versionPages=computed(()=>Math.max(1,Math.ceil((detail.value?.versionTotal||0)/20))),feedbackPages=computed(()=>Math.max(1,Math.ceil((detail.value?.feedbackTotal||0)/20)));
const filters=computed(()=>query.value.trim()||assignment.value!=='0'||author.value!=='0'||state.value!=='ALL');
const dimensions=[{code:'S',name:'科学性'},{code:'A',name:'准确性'},{code:'C',name:'完整性'},{code:'L',name:'逻辑性'}];
const tabs=[{id:'ALL',name:'全部作品',count:'entry_count'},{id:'DRAFT',name:'仅草稿',count:'draft_entries'},{id:'PENDING',name:'有待评版本',count:'pending_entries'},{id:'FEEDBACK',name:'有未解决反馈',count:'feedback_entries'}];
const actions:Record<string,string>={REPLY:'作者已回应',ADOPT:'作者已采纳',IGNORE:'作者已说明忽略'};
const number=(v:any)=>v==null?'—':Number(v).toFixed(1);
const date=(s:string)=>new Date(s).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false});
async function load(){const g=++generation;loading.value=true;error.value='';try{const params=new URLSearchParams({q:query.value,assignmentId:assignment.value,authorId:author.value,state:state.value,sort:sort.value,page:String(page.value)});const r=await api(`/courses/${props.courseId}/progress-workbench?${params}`);if(!alive||g!==generation)return;data.value=r;if(page.value>pages.value){page.value=pages.value;await load();}}catch(e:any){if(g===generation){error.value=e.message;data.value=null;}}finally{if(g===generation)loading.value=false;}}
function filter(){clearTimeout(debounce);page.value=1;void load();}function search(){clearTimeout(debounce);generation++;page.value=1;loading.value=true;debounce=setTimeout(load,250);}
function reset(){query.value='';assignment.value='0';author.value='0';state.value='ALL';sort.value='recent';filter();}
async function turn(delta:number){page.value+=delta;await load();document.querySelector('.progress-list-title')?.scrollIntoView({behavior:'smooth',block:'start'});}
async function fetchDetail(){const g=++detailGeneration;detailLoading.value=true;detailError.value='';try{const params=new URLSearchParams({versionPage:String(versionPage.value),feedbackPage:String(feedbackPage.value),feedbackState:feedbackState.value});const d=await api(`/progress-entries/${detailId}?${params}`);if(alive&&g===detailGeneration){if(d.entry.course_id!==props.courseId)throw Error('作品不属于当前课程');detail.value=d;}}catch(e:any){if(g===detailGeneration){detail.value=null;detailError.value=e.message;}}finally{if(g===detailGeneration)detailLoading.value=false;}}
async function open(e:any,which='versions'){returnFocus=document.activeElement as HTMLElement;detailId=e.id;tab.value=which;versionPage.value=1;feedbackPage.value=1;feedbackState.value='OPEN';detail.value=null;await nextTick();dialog.value?.showModal();await fetchDetail();}
function openById(id:number){const e=entries.value.find((x:any)=>x.id===id)||{id};void open(e);}
function close(){detailGeneration++;dialog.value?.close();detail.value=null;detailLoading.value=false;returnFocus?.focus();}
function version(id:number){if(dialog.value?.open)close();emit('open-version',id);}
function feedback(f:any){const target={submissionId:f.submission_id,paragraphId:f.paragraph_id};close();emit('open-feedback',target);}
function feedbackFilter(){feedbackPage.value=1;void fetchDetail();}
watch(()=>[props.courseId,props.staff,props.userId],()=>{clearTimeout(debounce);generation++;close();exportRequest.value=null;data.value=null;query.value='';assignment.value='0';author.value='0';state.value='ALL';sort.value='recent';page.value=1;void load();},{immediate:true});
onBeforeUnmount(()=>{alive=false;generation++;detailGeneration++;clearTimeout(debounce);});
</script>
<template>
<section class="page progress-page">
 <div class="page-heading"><div><span class="eyebrow">{{ staff?'课程教学进展':'每一次修订，都有迹可循' }}</span><h1>{{ staff?'教学进展':'学习轨迹' }}</h1><p>按作品回看提交、四维评价和反馈处理。</p></div><div class="progress-export-actions"><button class="btn secondary" :disabled="loading||!data" @click="exportCourse">导出当前筛选 CSV</button><button class="btn secondary" :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新记录</button></div></div>
 <div class="progress-filters"><label class="search-box"><Search :size="17"/><input v-model="query" aria-label="搜索轨迹作品" maxlength="80" placeholder="搜索作品、作业或作者" @input="search"/></label><select v-model="assignment" aria-label="按作业筛选轨迹" @change="filter"><option value="0">全部作业</option><option v-for="a in data?.assignments||[]" :key="a.id" :value="String(a.id)">{{ a.title }}</option></select><select v-if="staff" v-model="author" aria-label="按作者筛选轨迹" @change="filter"><option value="0">全部作者</option><option v-for="a in data?.authors||[]" :key="a.id" :value="String(a.id)">{{ a.display_name }}{{ a.current_member?'':' · 已移出课程' }}</option></select><select v-model="sort" aria-label="轨迹排序" @change="filter"><option value="recent">最近编辑</option><option value="feedback">未解决反馈优先</option><option value="pending">待评版本优先</option><option value="quality">最近质量分优先</option></select><button v-if="filters" class="text-btn" @click="reset">清除筛选</button></div>
 <div v-if="error" class="global-error" role="alert"><AlertCircle :size="18"/>{{ error }}<button class="text-btn" @click="load">重试读取</button></div>
 <template v-if="data">
  <div class="progress-stats"><article class="stat-card"><span><FileText :size="17"/>{{ staff?'课程作品':'已开始作品' }}</span><strong>{{ stats.entry_count }}<small>篇</small></strong></article><article class="stat-card"><span><History :size="17"/>累计提交</span><strong>{{ stats.submissions }}<small>个版本</small></strong><p>{{ stats.pending_versions }} 个版本尚无正式评价</p></article><article class="stat-card"><span><TrendingUp :size="17"/>最近质量均分</span><strong>{{ number(stats.latest_average) }}<small>/100</small></strong></article><article class="stat-card"><span><MessageSquare :size="17"/>未解决反馈</span><strong>{{ stats.open_feedback }}<small>条</small></strong></article></div>
  <TimeStatsPanel v-if="staff" :course-id="courseId" @open="openById" />
  <div class="section-title progress-list-title"><div><h2>{{ staff?'作品与版本进展':'我的作品档案' }}</h2></div></div>
  <div class="progress-state-tabs" role="group" aria-label="按进展状态筛选"><button v-for="t in tabs" :key="t.id" :aria-pressed="state===t.id" :class="{active:state===t.id}" @click="state=t.id;filter()">{{ t.name }}<span class="badge">{{ stats[t.count]||0 }}</span></button></div>
  <div class="progress-results" :aria-busy="loading"><p v-if="loading" class="empty-text" role="status">正在读取课程记录…</p>
   <template v-else><article v-for="e in entries" :key="e.id" class="progress-entry" :data-entry-id="e.id">
    <div class="progress-entry-head"><span class="progress-entry-symbol"><FileText :size="21"/></span><div><h2>{{ e.title }}</h2><p>{{ e.author_name }} · {{ e.assignment_title }}</p></div><span class="grow"></span><div class="progress-latest-score"><strong>{{ number(e.latest_score) }}</strong><span>{{ e.latest_score==null?'尚无教师评分':'最近已评分版本' }}</span></div></div>
    <div class="progress-entry-body"><div class="version-journey"><div class="section-label"><History :size="15"/>提交轨迹 <small v-if="e.submission_count>5">最近 5 / {{ e.submission_count }} 次</small></div><div class="version-journey-nodes"><button v-for="v in e.versions" :key="v.id" @click="version(v.id)"><span class="journey-point" :class="{graded:v.q_final!=null}">v{{ v.version_no }}</span><strong>{{ v.q_final==null?'待评审':`${number(v.q_final)} 分` }}</strong><small>{{ date(v.created_at) }}</small></button><div class="journey-draft"><span class="journey-point">r{{ e.revision }}</span><strong>当前草稿</strong><small>{{ date(e.updated_at) }}</small></div></div></div>
     <div v-if="e.latest_score!=null" class="progress-dimension-grid"><div v-for="d in dimensions" :key="d.code"><span>{{ d.name }}</span><strong>{{ number(e.latest_dimensions[d.code]) }}</strong><div class="progress-mini-bar"><i :style="{width:`${Math.max(0,Math.min(100,Number(e.latest_dimensions[d.code]||0)))}%`}"/></div></div></div><p v-else class="progress-ungraded">教师评分后显示</p>
    </div>
    <div class="progress-entry-foot"><button class="text-btn" @click="open(e,'feedback')"><MessageSquare :size="14"/>已解决 {{ e.feedback_resolved }} / {{ e.feedback_total }} 条反馈</button><span><ShieldCheck :size="14"/>{{ e.evidence_passed }} 条历史证据已通过</span><span class="progress-dwell" title="页面在前台且有操作时累计"><Clock :size="14"/>做题用时 {{ durationLabel(e.write_seconds) }}<template v-if="staff"> · 批改用时 {{ durationLabel(e.grade_seconds) }}</template></span><button class="text-btn" @click="open(e)">完整版本与反馈<History :size="14"/></button><button v-if="e.versions.length" class="text-btn" @click="version(e.versions[e.versions.length-1].id)">查看最近提交<ArrowUpRight :size="14"/></button><button v-else class="text-btn" @click="emit('assignments')">前往作业<ChevronRight :size="14"/></button></div>
   </article>
   <div v-if="!entries.length" class="empty card"><TrendingUp :size="32"/><h2>{{ filters?'没有匹配的作品':'轨迹从第一篇知识帖开始' }}</h2><p>{{ filters?'当前筛选范围内没有作品，请尝试其他作业或状态。':'开始作业并提交后，这里会保留版本与反馈记录。' }}</p><button class="btn primary" @click="filters?reset():emit('assignments')">{{ filters?'清除筛选':'查看课程作业' }}</button></div></template>
  </div>
  <div class="progress-pagination"><span class="muted">{{ data.total }} 篇匹配作品 · 第 {{ page }}/{{ pages }} 页</span><button class="btn secondary" :disabled="loading||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="loading||page>=pages" @click="turn(1)">下一页</button></div>
  <p class="progress-data-note"><ShieldCheck :size="14"/>{{ staff?'仅本课程教师与助教可查看全班作品进展。':'本页仅展示你的作品与评价记录。' }}</p>
 </template><p v-else-if="loading" class="empty-text" role="status">正在读取课程记录…</p>
</section>
<dialog ref="dialog" class="progress-dialog" aria-labelledby="progress-detail-title" @cancel.prevent="close"><header><div><h2 id="progress-detail-title">作品轨迹详情</h2></div><button class="icon-btn" aria-label="关闭轨迹详情" @click="close"><X :size="20"/></button></header>
 <div class="progress-detail-body"><p v-if="detailError" class="global-error" role="alert">{{ detailError }}<button class="text-btn" @click="fetchDetail">重试读取</button></p><template v-if="detail"><div class="progress-detail-title"><h3>{{ detail.entry.title }}</h3><p class="muted">{{ detail.entry.author_name }} · {{ detail.entry.assignment_title }}</p><button class="btn secondary" :disabled="detailLoading" @click="exportEntry">生成作品报告</button></div><div class="progress-detail-tabs" role="group" aria-label="轨迹详情内容"><button :aria-pressed="tab==='versions'" @click="tab='versions'">提交版本</button><button :aria-pressed="tab==='feedback'" @click="tab='feedback'">教师反馈跟进</button><button class="text-btn" :disabled="detailLoading" @click="fetchDetail"><RefreshCw :size="14"/>刷新详情</button></div>
  <section v-if="tab==='versions'" class="progress-version-list"><article v-for="v in detail.versions" :key="v.id" class="progress-version-row"><span class="journey-point" :class="{graded:v.q_final!=null}">v{{ v.version_no }}</span><div><strong>{{ v.q_final==null?'待教师评审':`${number(v.q_final)} 分` }}</strong><p class="muted">{{ date(v.created_at) }} <template v-if="v.evaluation_revision">· 评价 r{{ v.evaluation_revision }}</template><template v-if="v.grade_seconds!=null"> · 批改用时 {{ durationLabel(v.grade_seconds) }}</template></p></div><button class="btn secondary" :disabled="detailLoading" @click="version(v.id)">阅读提交版本<ArrowUpRight :size="14"/></button></article><p v-if="!detail.versions.length" class="empty-text">作品仍是草稿，尚无提交版本。</p><div class="progress-pagination"><span>{{ detail.versionTotal }} 个版本 · 第 {{ versionPage }}/{{ versionPages }} 页</span><button class="btn secondary" :disabled="detailLoading||versionPage<=1" @click="versionPage--;fetchDetail()">上一页版本</button><button class="btn secondary" :disabled="detailLoading||versionPage>=versionPages" @click="versionPage++;fetchDetail()">下一页版本</button></div></section>
  <section v-else class="progress-feedback-list"><div class="progress-feedback-filter"><label>反馈状态<select v-model="feedbackState" aria-label="筛选轨迹反馈" @change="feedbackFilter"><option value="OPEN">未解决</option><option value="ALL">全部反馈</option><option value="RESOLVED">已解决</option></select></label></div><article v-for="f in detail.feedback" :key="f.id" class="progress-feedback-row"><div class="progress-feedback-meta"><span class="badge blue">{{ f.indicator_code }}</span><strong>v{{ f.version_no }} · {{ f.teacher_name }}</strong><span class="badge" :class="f.resolved?'green':'orange'">{{ f.resolved?'教师已确认解决':'待教师确认解决' }}</span></div><p class="progress-feedback-text">{{ f.body }}</p><blockquote>{{ f.original_text }}</blockquote><p v-if="f.author_action" class="muted">{{ actions[f.author_action] }}{{ f.resolved?'':' · 仍待教师确认' }}</p><div class="progress-feedback-footer"><small class="muted">{{ date(f.created_at) }}</small><button class="text-btn" :disabled="detailLoading" @click="feedback(f)">查看批注并定位<ArrowUpRight :size="14"/></button></div></article><p v-if="!detail.feedback.length" class="empty-text">当前状态下没有反馈记录。</p><div class="progress-pagination"><span>{{ detail.feedbackTotal }} 条反馈 · 第 {{ feedbackPage }}/{{ feedbackPages }} 页</span><button class="btn secondary" :disabled="detailLoading||feedbackPage<=1" @click="feedbackPage--;fetchDetail()">上一页反馈</button><button class="btn secondary" :disabled="detailLoading||feedbackPage>=feedbackPages" @click="feedbackPage++;fetchDetail()">下一页反馈</button></div></section>
 </template><p v-if="detailLoading" class="empty-text" role="status">正在读取轨迹详情…</p></div><footer><span class="muted">仅展示有权限的历史记录，不包含教师私有评分草稿。</span><button class="btn secondary" @click="close">关闭详情</button></footer>
</dialog>
<ReportExport v-if="exportRequest" :request="exportRequest" @close="exportRequest=null" />
</template>
<style scoped>
.progress-export-actions{display:flex;gap:10px;flex-wrap:wrap}
.progress-filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}.progress-filters .search-box{flex:1;min-width:220px}.progress-filters select{max-width:240px}.progress-filters select,.progress-feedback-filter select{padding:9px 10px;border:1px solid var(--border);border-radius:7px;color:var(--text);background:var(--paper)}.progress-scope-note{font-size:12px;color:var(--muted);margin:14px 0}.progress-state-tabs{display:flex;gap:20px;border-bottom:1px solid var(--border);margin:18px 0;flex-wrap:wrap}.progress-state-tabs button{padding:10px 0;display:flex;gap:7px;align-items:center;border:0;border-bottom:2px solid transparent;background:none;color:var(--muted)}.progress-state-tabs button.active{border-bottom-color:var(--blue);color:var(--text)}.progress-pagination{display:flex;gap:10px;align-items:center;margin:18px 0}.progress-pagination>span{flex:1;font-size:12px;color:var(--muted)}.progress-dialog{width:min(880px,calc(100vw - 48px));max-height:90vh;padding:0;border:1px solid var(--border);border-radius:14px;background:var(--paper);color:var(--text)}.progress-dialog::backdrop{background:#11182766}.progress-dialog header,.progress-dialog footer{padding:20px 26px;display:flex;align-items:center;justify-content:space-between;gap:16px;background:var(--paper)}.progress-dialog header{border-bottom:1px solid var(--border)}.progress-dialog footer{border-top:1px solid var(--border)}.progress-dialog footer>span{font-size:12px}.progress-detail-body{max-height:64vh;overflow:auto;padding:22px 26px}.progress-detail-title{margin-bottom:18px}.progress-detail-tabs{display:flex;gap:16px;align-items:center;border-bottom:1px solid var(--border);margin-bottom:18px}.progress-detail-tabs>button{padding:10px 0;border:0;border-bottom:2px solid transparent;color:var(--muted);background:none}.progress-detail-tabs>button[aria-pressed=true]{border-bottom-color:var(--blue);color:var(--text)}.progress-detail-tabs>.text-btn{margin-left:auto}.progress-version-row{padding:16px 0;border-bottom:1px solid var(--border);display:flex;gap:18px;align-items:center}.progress-version-row>div{flex:1}.progress-version-row p{margin:3px 0;font-size:12px}.progress-feedback-filter{display:flex;gap:20px;align-items:center;font-size:12px}.progress-feedback-filter select{margin-left:12px}.progress-feedback-row{border:1px solid var(--border);padding:18px;margin-top:16px;border-radius:10px}.progress-feedback-meta{display:flex;gap:10px;align-items:center;font-size:12px;flex-wrap:wrap}.progress-feedback-meta>span:last-child{margin-left:auto}.progress-feedback-text{white-space:pre-wrap;overflow-wrap:anywhere;margin:14px 0}.progress-feedback-row blockquote{border-left:2px solid var(--border);margin:12px 0;padding:8px 12px;color:var(--muted);background:var(--surface);font-size:12px;overflow-wrap:anywhere;white-space:pre-wrap}.progress-feedback-footer{display:flex;gap:14px;justify-content:space-between;align-items:center}.progress-entry-foot{flex-wrap:wrap}.progress-entry-head h2,.progress-detail-title h3{overflow-wrap:anywhere}
</style>
